function StatusPill({ status }) {
  const className =
    status === "Completed" ? "completed" : status === "In Progress" ? "in-progress" : "not-started";
  return <span className={`status-pill ${className}`}>{status}</span>;
}

function ProgressSection({ record, onEdit }) {
  const { departments, done, total, percent } = overallStats(record);
  let angle = 0;
  const slices = [];

  departments.forEach((department) => {
    [
      { count: department.done, complete: true },
      { count: department.total - department.done, complete: false },
    ].forEach(({ count, complete }) => {
      if (!count) return;
      const start = angle;
      angle += (count / total) * 360;
      slices.push({
        key: `${department.id}-${complete}`,
        path: pieSlice(start, angle),
        color: department.color,
        complete,
        label: `${department.name}: ${count} ${complete ? "done" : "still to do"}`,
      });
    });
  });

  return (
    <section className="surface progress-section" aria-labelledby="progress-heading">
      <div className="section-heading">
        <div>
          <p className="eyebrow">THE COMPLETE PICTURE</p>
          <h2 id="progress-heading">Progress by department</h2>
        </div>
        <button className="button secondary" onClick={onEdit}>Edit changes</button>
      </div>

      <div className="progress-layout">
        <div className="pie-column">
          <svg
            className="pie-chart"
            viewBox="0 0 240 240"
            role="img"
            aria-label={`Overall progress: ${percent} percent, ${done} of ${total} details done. Solid slices are done; faded slices are still to do.`}
          >
            <title>Combined department progress</title>
            {slices.map((slice) => (
              <path
                key={slice.key}
                d={slice.path}
                fill={slice.color}
                fillOpacity={slice.complete ? 1 : 0.22}
                stroke="#fff"
                strokeWidth="2"
              >
                <title>{slice.label}</title>
              </path>
            ))}
          </svg>
          <p className="pie-note">
            <span className="sample-solid" /> Done
            <span className="sample-faded" /> Still to do
          </p>
          <p className="muted small">Slice sizes reflect each department’s number of details.</p>
        </div>

        <div>
          <div className="overall-summary">
            <span className="overall-percent">{percent}%</span>
            <div>
              <h3>Overall completion</h3>
              <p>{done} of {total} details done</p>
            </div>
          </div>
          <div className="department-key">
            {departments.map((department) => (
              <div key={department.id} className="department-row">
                <div className="department-top">
                  <span className="department-name">
                    <span className="color-dot" style={{ background: department.color }} />
                    {department.name}
                  </span>
                  <StatusPill status={department.status} />
                </div>
                <p className="department-count">
                  {department.done}/{department.total} · {department.percent}%
                </p>
                <div className="missing-tags">
                  {department.missing.length ? department.missing.map((label) => (
                    <span className="missing-tag" key={label}>{label}</span>
                  )) : <span className="all-done">All details complete</span>}
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="bar-section">
        <h3>Department completion</h3>
        <div className="bar-axis" aria-hidden="true">
          <span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span>
        </div>
        {departments.map((department) => (
          <div className="bar-row" key={department.id}>
            <span className="bar-label">{department.name}</span>
            <div
              className="bar-track"
              role="progressbar"
              aria-label={`${department.name} completion`}
              aria-valuenow={department.percent}
              aria-valuemin={0}
              aria-valuemax={100}
            >
              <div style={{ width: `${department.percent}%`, background: department.color }} />
            </div>
            <span className="bar-value">{department.percent}%</span>
          </div>
        ))}
      </div>
    </section>
  );
}

function AdSlot({ ad, image, onUpload, onRemove }) {
  const inputId = `upload-${ad.id}`;
  const inputRef = useRef(null);

  return (
    <div>
      <p className="ads-label">{ad.label}</p>
      <div className={`ad-space ${ad.tall ? "" : "small-ad"}`}>
        {image ? (
          <>
            <img className="ad-image" src={image.url} alt={image.name} />
            <p className="ad-file-name">{image.name}</p>
            <div className="ad-actions">
              <button
                type="button"
                className="button neutral small-button"
                onClick={() => inputRef.current?.click()}
              >Replace</button>
              <button
                type="button"
                className="button neutral small-button"
                onClick={onRemove}
              >Remove</button>
            </div>
          </>
        ) : (
          <>
            <span className="ad-icon" aria-hidden="true">⬆</span>
            <h3>{ad.title}</h3>
            <p>{ad.body}</p>
            <button
              type="button"
              className="button primary small-button"
              onClick={() => inputRef.current?.click()}
            >Upload ad</button>
          </>
        )}
        <label className="sr-only" htmlFor={inputId}>
          {image ? `Replace advertisement image for ${ad.title}` : `Upload advertisement image for ${ad.title}`}
        </label>
        <input
          ref={inputRef}
          id={inputId}
          type="file"
          accept="image/*"
          className="sr-only"
          onChange={(event) => {
            const file = event.target.files?.[0];
            if (!file) return;
            onUpload({
              name: file.name,
              url: URL.createObjectURL(file),
            });
            event.target.value = "";
          }}
        />
      </div>
    </div>
  );
}

export default function App() {
  const [serials, setSerials] = useState(createSamples);
  const [selectedId, setSelectedId] = useState(null);
  const [view, setView] = useState("landing");
  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(emptyFields);
  const [titleError, setTitleError] = useState("");
  const [menu, setMenu] = useState(null);
  const [query, setQuery] = useState("");
  const [activeStage, setActiveStage] = useState(null);
  const [toast, setToast] = useState(null);
  const [chatOpen, setChatOpen] = useState(false);
  const [chatText, setChatText] = useState("");
  const [messages, setMessages] = useState([
    {
      id: "welcome",
      role: "assistant",
      text: "Welcome! This is a local demo chat. Ask about progress, stages, or saving a serial. No messages are sent to a server.",
    },
  ]);
  const [adImages, setAdImages] = useState({});

  const serialMenuRef = useRef(null);
  const kebabMenuRef = useRef(null);
  const searchRef = useRef(null);
  const serialButtonRef = useRef(null);
  const kebabButtonRef = useRef(null);
  const titleRef = useRef(null);
  const toastTimerRef = useRef(null);
  const stagePanelRef = useRef(null);
  const chatLogRef = useRef(null);
  const chatInputRef = useRef(null);

  const selected = serials.find((serial) => serial.id === selectedId) || null;
  const sorted = [...serials].sort((a, b) => b.createdAt.localeCompare(a.createdAt));
  const tokens = query.toLowerCase().trim().split(/\s+/).filter(Boolean);
  const filtered = sorted.filter((record) => {
    const text = searchText(record);
    return tokens.every((token) => text.includes(token));
  });
  const stageDepartment = DEPARTMENTS.find((item) => item.id === activeStage);
  const stage = selected && activeStage ? selected.stages[activeStage] : null;
  const activeCount = serials.filter((record) =>
    DEPARTMENTS.some((item) => record.stages[item.id].status === "In Progress"),
  ).length;
  const completedCount = serials.filter((record) =>
    DEPARTMENTS.every((item) => record.stages[item.id].status === "Completed"),
  ).length;

  useEffect(() => {
    if (menu === "serials") searchRef.current?.focus();
  }, [menu]);

  useEffect(() => {
    function onPointerDown(event) {
      const container = menu === "serials" ? serialMenuRef.current : kebabMenuRef.current;
      if (menu && container && !container.contains(event.target)) setMenu(null);
    }
    function onKeyDown(event) {
      if (event.key !== "Escape" || !menu) return;
      setMenu(null);
      (menu === "serials" ? serialButtonRef : kebabButtonRef).current?.focus();
    }
    document.addEventListener("pointerdown", onPointerDown);
    document.addEventListener("keydown", onKeyDown);
    return () => {
      document.removeEventListener("pointerdown", onPointerDown);
      document.removeEventListener("keydown", onKeyDown);
    };
  }, [menu]);

  useEffect(() => {
    if (editing) titleRef.current?.focus();
  }, [editing, view]);

  useEffect(() => {
    if (activeStage && selectedId) {
      stagePanelRef.current?.scrollIntoView({ behavior: "smooth", block: "nearest" });
      stagePanelRef.current?.focus({ preventScroll: true });
    }
  }, [activeStage, selectedId]);

  useEffect(() => {
    if (chatOpen) {
      chatInputRef.current?.focus();
      if (chatLogRef.current) chatLogRef.current.scrollTop = chatLogRef.current.scrollHeight;
    }
  }, [chatOpen]);

  useEffect(() => {
    if (chatLogRef.current) chatLogRef.current.scrollTop = chatLogRef.current.scrollHeight;
  }, [messages]);

  useEffect(() => () => clearTimeout(toastTimerRef.current), []);

  function notify(message) {
    clearTimeout(toastTimerRef.current);
    setToast({ message, id: Date.now() });
    toastTimerRef.current = setTimeout(() => setToast(null), 3800);
  }

  function goHome() {
    setView("landing");
    setSelectedId(null);
    setEditing(false);
    setActiveStage(null);
    setMenu(null);
    setTitleError("");
  }

  function openSerial(record) {
    setSelectedId(record.id);
    setView("detail");
    setEditing(false);
    setActiveStage(null);
    setMenu(null);
    setTitleError("");
  }

  function addDetails() {
    setSelectedId(null);
    setDraft(emptyFields());
    setView("detail");
    setEditing(true);
    setActiveStage(null);
    setMenu(null);
    setTitleError("");
  }

  function startEditing() {
    if (!selected) return;
    setDraft({ ...selected.fields });
    setTitleError("");
    setEditing(true);
    setMenu(null);
  }

  function saveDetails(event) {
    event.preventDefault();
    if (!draft.title.trim()) {
      setTitleError("Please enter a title before saving.");
      titleRef.current?.focus();
      return;
    }

    const fields = Object.fromEntries(
      Object.entries(draft).map(([key, value]) => [key, String(value).trim()]),
    );

    if (selected) {
      setSerials((previous) =>
        previous.map((record) => record.id === selected.id ? { ...record, fields } : record),
      );
    } else {
      const nextNumber = Math.max(
        0,
        ...serials.map((record) => Number(record.id.replace("SR-", "")) || 0),
      ) + 1;
      const record = {
        id: `SR-${String(nextNumber).padStart(3, "0")}`,
        createdAt: new Date().toISOString(),
        fields,
        stages: emptyStages(),
      };
      setSerials((previous) => [record, ...previous]);
      setSelectedId(record.id);
    }

    setEditing(false);
    setTitleError("");
    notify("Changes saved");
  }

  function cancelEdit() {
    setTitleError("");
    if (selected) setEditing(false);
    else goHome();
  }

  function chooseStage(id) {
    setMenu(null);
    if (!selected) {
      notify("Please open a serial first. Save a new serial before updating its stages.");
      return;
    }
    setActiveStage(id);
  }

  function updateStage(patch) {
    if (!selected || !activeStage) return;
    setSerials((previous) => previous.map((record) =>
      record.id === selected.id
        ? {
            ...record,
            stages: {
              ...record.stages,
              [activeStage]: { ...record.stages[activeStage], ...patch },
            },
          }
        : record,
    ));
    notify("Changes saved");
  }

  function sendChat(event) {
    event.preventDefault();
    const text = chatText.trim();
    if (!text) return;

    const normalized = text.toLowerCase();
    let reply = "This demo supports questions about progress, stages, and saving. Connect a chat API to provide live replies.";

    if (/progress|percent|complete|done/.test(normalized)) {
      if (selected) {
        const progress = overallStats(selected);
        reply = `${selected.fields.title} is ${progress.percent}% complete: ${progress.done} of ${progress.total} details done. Each filled field, stage date, and completed stage counts as one detail.`;
      } else {
        reply = "Open a serial to see its progress. The progress section combines form fields, stage dates, and completed stages.";
      }
    } else if (/stage|schedule|status/.test(normalized)) {
      reply = "Open a saved serial, then use the three-dot menu to select a department. Stage status and date changes save immediately in this session.";
    } else if (/save|add|edit/.test(normalized)) {
      reply = "Use Add details to create a serial. A title is required. Save changes switches to the read-only view; Edit changes lets you update it. This demo stores records in memory only.";
    } else if (/hello|hi\b|help/.test(normalized)) {
      reply = "Hello! Ask about progress, stages, or saving. This is a local, rule-based demo chat, not a live support service.";
    }

    setMessages((previous) => [
      ...previous,
      { id: `${Date.now()}-user`, role: "user", text },
      { id: `${Date.now()}-assistant`, role: "assistant", text: reply },
    ]);
    setChatText("");
  }

  return (
    <>
      <style>{CSS}</style>
      <div className="app-shell">
        <header className="navbar">
          <button className="brand" onClick={goHome} aria-label={`${BRAND}, landing page`}>
            <img src={LOGO} alt="TrueHunt" className="brand-logo" />
            <span className="brand-domain">.in</span>
          </button>

          <div className="menu-container" ref={serialMenuRef}>
            <button
              className="nav-button"
              ref={serialButtonRef}
              aria-expanded={menu === "serials"}
              aria-controls="serials-dropdown"
              onClick={() => {
                if (menu === "serials") setMenu(null);
                else {
                  setQuery("");
                  setMenu("serials");
                }
              }}
            >
              Serials <span aria-hidden="true">⌄</span>
            </button>
            {menu === "serials" && (
              <div className="dropdown serial-dropdown" id="serials-dropdown">
                <label className="dropdown-search-label" htmlFor="serial-search">
                  Search all serial details
                </label>
                <input
                  ref={searchRef}
                  id="serial-search"
                  type="search"
                  placeholder="Title, ID, director, status, date…"
                  value={query}
                  onChange={(event) => setQuery(event.target.value)}
                  autoComplete="off"
                />
                <p className="dropdown-count" role="status">
                  {query.trim()
                    ? `${filtered.length} of ${serials.length} serials`
                    : `${serials.length} serials`}
                </p>
                <div className="serial-list">
                  {filtered.length ? filtered.map((record) => (
                    <button
                      className="serial-option"
                      key={record.id}
                      onClick={() => openSerial(record)}
                    >
                      <span className="serial-option-title">{record.fields.title}</span>
                      <span className="serial-option-meta">
                        {record.id} · {record.fields.director || "Director not provided"}
                      </span>
                    </button>
                  )) : (
                    <p className="empty-search">No match. Try another title, number, date, or stage status.</p>
                  )}
                </div>
              </div>
            )}
          </div>

          <button className="nav-button add-button" onClick={addDetails}>
            Add details <span aria-hidden="true">+</span>
          </button>

          <div className="menu-container kebab-container" ref={kebabMenuRef}>
            <button
              className="nav-button kebab"
              ref={kebabButtonRef}
              aria-label="Open department options"
              aria-expanded={menu === "stages"}
              aria-controls="stages-dropdown"
              onClick={() => setMenu(menu === "stages" ? null : "stages")}
            >
              ⋮
            </button>
            {menu === "stages" && (
              <div className="dropdown stage-dropdown" id="stages-dropdown">
                <p className="eyebrow">DEPARTMENTS</p>
                {DEPARTMENTS.map((department) => (
                  <button
                    key={department.id}
                    className="stage-menu-option"
                    onClick={() => chooseStage(department.id)}
                  >
                    <span>{department.name}</span>
                    {selected && <StatusPill status={selected.stages[department.id].status} />}
                  </button>
                ))}
              </div>
            )}
          </div>
        </header>

        <div className="workspace">
          <main className="main-content">
            {view === "landing" ? (
              <>
                <section className="about" aria-labelledby="about-heading">
                  <div className="about-text">
                    <p className="eyebrow">ABOUT THE ORGANIZATION</p>
                    <h1 id="about-heading">{ABOUT.name}</h1>
                    <p className="about-tagline">{ABOUT.tagline}</p>
                    <p className="about-body">{ABOUT.description}</p>
                    <div className="about-actions">
                      <button className="button primary" onClick={addDetails}>Add details</button>
                      <button
                        className="about-link"
                        onClick={() =>
                          document.getElementById("recent-serials")?.scrollIntoView({ behavior: "smooth", block: "start" })
                        }
                      >View recent serials ↓</button>
                    </div>
                  </div>
                  <div className="about-side">
                    <dl className="about-stats">
                      <div><dt>Serials tracked</dt><dd>{serials.length}</dd></div>
                      <div><dt>In progress</dt><dd>{activeCount}</dd></div>
                      <div><dt>Completed</dt><dd>{completedCount}</dd></div>
                    </dl>
                    <ul className="about-points">
                      {ABOUT.highlights.map((item) => (
                        <li key={item.title}>
                          <strong>{item.title}</strong>
                          <span>{item.text}</span>
                        </li>
                      ))}
                    </ul>
                  </div>
                </section>

                <div className="landing-heading" id="recent-serials">
                  <p className="eyebrow">YOUR PRODUCTION WORKSPACE</p>
                  <div className="heading-line">
                    <h2>Recent serials</h2>
                    <span className="count-badge">{serials.length} total</span>
                  </div>
                  <p className="muted">Your latest six serials, newest first. Open a card to manage its details and stages.</p>
                </div>
                <div className="cards">
                  {sorted.slice(0, 6).map((record, index) => {
                    const progress = overallStats(record);
                    return (
                      <button
                        className="serial-card"
                        style={{ "--stripe": DEPARTMENTS[index % DEPARTMENTS.length].color }}
                        key={record.id}
                        onClick={() => openSerial(record)}
                        aria-label={`Open ${record.fields.title}, ${record.id}, ${progress.percent}% complete`}
                      >
                        <span className="card-id">{record.id}</span>
                        <h2>{record.fields.title}</h2>
                        <div className="card-meta">
                          <div>
                            <span className="meta-label">Director</span>
                            <span>{record.fields.director || "Not provided"}</span>
                          </div>
                          <div>
                            <span className="meta-label">Expected release date</span>
                            <span>{formatDate(record.fields.expectedReleaseDate)}</span>
                          </div>
                        </div>
                        <p className="card-stage">Current stage: {currentStage(record)}</p>
                        <div className="card-progress-text">
                          <span>{progress.done}/{progress.total} details</span>
                          <span>{progress.percent}%</span>
                        </div>
                        <div className="mini-track" aria-hidden="true">
                          <div style={{ width: `${progress.percent}%` }} />
                        </div>
                      </button>
                    );
                  })}
                </div>
                <p className="session-note">
                  Demo workspace: records are held in memory. Refreshing the page resets changes.
                </p>
              </>
            ) : (
              <>
                <button className="back-link" onClick={goHome}>← Recent serials</button>
                <section className="surface" aria-labelledby="record-heading">
                  <div className="section-heading">
                    <div className="record-heading">
                      <p className="eyebrow">{editing ? "SERIAL DETAILS" : "SAVED RECORD"}</p>
                      <h1 id="record-heading">
                        {editing ? selected ? "Edit serial details" : "Add serial details" : selected?.fields.title}
                      </h1>
                      <p className="record-id">
                        {selected ? selected.id : "A serial ID will be assigned when you save."}
                      </p>
                    </div>
                    {!editing && selected && (
                      <button className="button secondary" onClick={startEditing}>Edit changes</button>
                    )}
                  </div>

                  {editing ? (
                    <form onSubmit={saveDetails} noValidate>
                      <div className="form-grid">
                        {FIELDS.map((field) => (
                          <div className="field" key={field.key}>
                            <label className="field-label" htmlFor={`field-${field.key}`}>
                              {field.label}
                              {field.key === "title" && <span className="required"> *</span>}
                            </label>
                            <input
                              id={`field-${field.key}`}
                              ref={field.key === "title" ? titleRef : undefined}
                              type={field.type}
                              min={field.type === "number" ? "0" : undefined}
                              step={field.type === "number" ? "any" : undefined}
                              value={draft[field.key]}
                              required={field.key === "title"}
                              aria-invalid={field.key === "title" && !!titleError}
                              aria-describedby={field.key === "title" && titleError ? "title-error" : undefined}
                              className={field.key === "title" && titleError ? "input-error" : ""}
                              placeholder={field.type === "date" ? undefined : `Enter ${field.label.toLowerCase()}`}
                              onChange={(event) => {
                                const value = event.target.value;
                                setDraft((previous) => ({ ...previous, [field.key]: value }));
                                if (field.key === "title" && value.trim()) setTitleError("");
                              }}
                            />
                            {field.key === "title" && titleError && (
                              <p id="title-error" className="inline-error" role="alert">{titleError}</p>
                            )}
                          </div>
                        ))}
                      </div>
                      <div className="form-actions">
                        <button className="button primary" type="submit">Save changes</button>
                        <button className="button neutral" type="button" onClick={cancelEdit}>Cancel</button>
                      </div>
                    </form>
                  ) : selected && (
                    <div className="form-grid">
                      {FIELDS.map((field) => {
                        const value = selected.fields[field.key];
                        return (
                          <div className="field" key={field.key}>
                            <span className="field-label">{field.label}</span>
                            <p className={`read-value ${filled(value) ? "" : "empty"}`}>
                              {filled(value)
                                ? field.type === "date" ? formatDate(value) : value
                                : "Not provided"}
                            </p>
                          </div>
                        );
                      })}
                    </div>
                  )}
                </section>

                {selected && stage && stageDepartment && (
                  <section
                    className="surface stage-panel"
                    style={{ "--stage-color": stageDepartment.color }}
                    ref={stagePanelRef}
                    tabIndex={-1}
                    aria-labelledby="stage-heading"
                  >
                    <div className="section-heading">
                      <div>
                        <p className="eyebrow">DEPARTMENT UPDATE</p>
                        <h2 id="stage-heading">{stageDepartment.name}</h2>
                      </div>
                      <button
                        className="button neutral"
                        onClick={() => setActiveStage(null)}
                        aria-label="Close stage panel"
                      >Close ×</button>
                    </div>
                    <div className="stage-panel-content">
                      <div>
                        <span className="field-label" id="stage-status-label">Status</span>
                        <div className="status-options" role="group" aria-labelledby="stage-status-label">
                          {STATUSES.map((status) => (
                            <button
                              key={status}
                              type="button"
                              className={`status-choice ${
                                status === "Completed" ? "completed" : status === "In Progress" ? "in-progress" : "not-started"
                              } ${stage.status === status ? "active" : ""}`}
                              aria-pressed={stage.status === status}
                              onClick={() => updateStage({ status })}
                            >{status}</button>
                          ))}
                        </div>
                      </div>
                      <div>
                        <label className="field-label" htmlFor={`stage-date-${activeStage}`}>Stage date</label>
                        <input
                          id={`stage-date-${activeStage}`}
                          type="date"
                          value={stage.date}
                          onChange={(event) => updateStage({ date: event.target.value })}
                        />
                      </div>
                    </div>
                    <p className="muted small stage-note">
                      Stage updates save immediately in memory. A stage date and a completed status each count as one detail.
                    </p>
                  </section>
                )}

                {selected && !editing && <ProgressSection record={selected} onEdit={startEditing} />}
                <p className="session-note">Changes are stored for this session only. Connect an API for permanent storage.</p>
              </>
            )}
          </main>

          <aside className="ads-rail" aria-label="Advertisement space">
            {ADS.map((ad) => (
              <AdSlot
                key={ad.id}
                ad={ad}
                image={adImages[ad.id]}
                onUpload={(image) => setAdImages((previous) => ({ ...previous, [ad.id]: image }))}
                onRemove={() => setAdImages((previous) => {
                  const next = { ...previous };
                  delete next[ad.id];
                  return next;
                })}
              />
            ))}
          </aside>
        </div>

        {chatOpen ? (
          <section className="chatbox" aria-labelledby="chat-heading">
            <div className="chat-header">
              <div>
                <h2 id="chat-heading">Workspace chat</h2>
                <p>Local demo · no server connection</p>
              </div>
              <button
                className="chat-close"
                aria-label="Close chat"
                onClick={() => setChatOpen(false)}
              >×</button>
            </div>
            <div
              className="chat-log"
              ref={chatLogRef}
              role="log"
              aria-label="Chat messages"
              aria-live="polite"
              aria-relevant="additions"
              tabIndex={0}
            >
              {messages.map((message) => (
                <div className={`chat-message ${message.role}`} key={message.id}>
                  <span className="chat-author">{message.role === "user" ? "YOU" : "WORKSPACE DEMO"}</span>
                  {message.text}
                </div>
              ))}
            </div>
            <form className="chat-form" onSubmit={sendChat}>
              <label className="sr-only" htmlFor="chat-message">Your message</label>
              <input
                ref={chatInputRef}
                id="chat-message"
                type="text"
                value={chatText}
                maxLength={2000}
                placeholder="Ask about progress…"
                onChange={(event) => setChatText(event.target.value)}
                autoComplete="off"
              />
              <button className="button primary" type="submit" disabled={!chatText.trim()}>Send</button>
            </form>
          </section>
        ) : (
          <div className="chat-launcher">
            <button
              className="chat-toggle"
              aria-label="Open workspace chat"
              aria-expanded="false"
              aria-controls="workspace-chat"
              onClick={() => setChatOpen(true)}
            >
              <span aria-hidden="true">💬</span>
            </button>
          </div>
        )}

        {toast && (
          <div className="toast" key={toast.id} role="status" aria-live="polite">
            <span>{toast.message}</span>
            <button className="toast-dismiss" aria-label="Dismiss notification" onClick={() => setToast(null)}>×</button>
          </div>
        )}
      </div>
    </>
  );
}

/* ---------- Styles ---------- */
const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Fraunces:wght@500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');

:root {
  font-family: 'Manrope', system-ui, sans-serif;
  color: #0a192f;
  background: #f8fafc;
  font-synthesis: none;
  --pink: #801823;
  --navy: #0a192f;
  --border: #e2e8f0;
  --rail-width: 270px;
}
*, *::before, *::after { box-sizing: border-box; }
html, body, #root {
  margin: 0 !important;
  padding: 0 !important;
  width: 100% !important;
  min-width: 0 !important;
  height: 100% !important;
  max-width: none !important;
  text-align: left !important;
}
body { display: block !important; min-width: 320px; }
#root { isolation: isolate; }
button, input { font: inherit; }
button { cursor: pointer; line-height: 1.35; }
button:disabled { cursor: not-allowed; opacity: .55; }
button:focus-visible, input:focus-visible, [tabindex]:focus-visible {
  outline: 3px solid #801823;
  outline-offset: 4px;
}
h1, h2, h3, p { margin: 0; }
h1, h2, h3 { font-family: 'Fraunces', Georgia, serif; }
h1 { font-size: clamp(2rem, 4vw, 3rem); line-height: 1.12; }
h2 { font-size: clamp(1.4rem, 2.5vw, 1.85rem); }
h3 { font-size: 1.2rem; }
input {
  width: 100%; min-width: 0; padding: 12px 13px;
  border: 1.5px solid var(--border); border-radius: 10px;
  color: var(--navy); background: #fff; line-height: 1.4;
  color-scheme: light;
}
input::placeholder { color: #94a3b8; opacity: 1; }
.app-shell { min-height: 100%; width: 100%; display: flex; flex-direction: column; }
.navbar {
  min-height: 82px; padding: 17px clamp(16px, 3vw, 42px);
  display: flex; align-items: center; gap: 14px;
  background: #fff;
  border-bottom: 1px solid var(--border);
  box-shadow: 0 1px 3px #0a192f0a; position: relative; z-index: 20;
}
.brand {
  border: 0; background: transparent; color: var(--navy);
  font-family: 'Fraunces', Georgia, serif; font-size: 1.9rem;
  font-weight: 700; padding: 3px 8px 3px 0; white-space: nowrap;
  display: flex; align-items: center; gap: 6px;
}
.brand-logo {
  height: 42px; width: auto; display: block; object-fit: contain;
}
.brand-domain {
  font-size: 1.15rem; font-weight: 700; color: #0a192f; letter-spacing: -0.02em;
  margin-top: 2px;
}
.nav-button {
  border: 1px solid var(--border); border-radius: 10px;
  background: #fff; color: var(--navy); padding: 11px 17px; font-weight: 800;
}
.nav-button:hover { background: #f1f5f9; }
.add-button { background: var(--pink); color: #fff; border-color: var(--pink); }
.add-button:hover { background: #69121b; }
.menu-container { position: relative; }
.kebab-container { margin-left: auto; }
.kebab { font-size: 27px; line-height: 1; padding: 9px 16px; }
.dropdown {
  position: absolute; top: calc(100% + 12px); left: 0;
  width: 410px; max-width: calc(100vw - 32px);
  background: white; border: 1px solid var(--border); border-radius: 16px;
  box-shadow: 0 20px 35px #0a192f1f; padding: 15px; color: var(--navy);
}
.serial-dropdown { width: 440px; }
.dropdown-search-label { display: block; font-size: .82rem; font-weight: 800; margin-bottom: 7px; }
.dropdown-count { color: #64748b; font-size: .83rem; font-weight: 800; margin: 13px 0 8px; }
.serial-list { max-height: 350px; overflow-y: auto; display: grid; gap: 5px; }
.serial-option {
  width: 100%; text-align: left; background: #f8fafc; border: 1px solid transparent;
  border-radius: 10px; padding: 12px; color: var(--navy);
}
.serial-option:hover { background: #fff5f5; border-color: #e8b4b8; }
.serial-option-title { display: block; font-weight: 800; margin-bottom: 4px; }
.serial-option-meta { display: block; color: #64748b; font-size: .8rem; }
.empty-search { padding: 24px 10px; color: #64748b; line-height: 1.6; }
.stage-dropdown { left: auto; right: 0; width: 405px; }
.stage-menu-option {
  width: 100%; border: 0; background: transparent; text-align: left;
  padding: 12px 8px; display: flex; gap: 10px; align-items: center;
  justify-content: space-between; color: var(--navy); border-radius: 8px;
  font-weight: 700; font-size: .87rem;
}
.stage-menu-option:hover { background: #fff5f5; }
.stage-menu-option + .stage-menu-option { border-top: 1px solid #edf2f7; }
.workspace {
  width: 100%; max-width: 1800px; margin: 0 auto;
  padding: 30px clamp(16px, 3vw, 42px) 28px;
  display: grid; grid-template-columns: minmax(0, 1fr) var(--rail-width);
  align-items: start; gap: 26px; flex: 1;
}
.main-content { min-width: 0; }
.eyebrow { font-size: .7rem; font-weight: 800; letter-spacing: .14em; color: #801823; margin-bottom: 9px; }
.muted { color: #64748b; line-height: 1.6; }
.small { font-size: .79rem; }
.landing-heading { margin: 52px 0 26px; scroll-margin-top: 20px; }
.heading-line h2 { font-size: clamp(1.8rem, 3.4vw, 2.4rem); line-height: 1.12; }
.landing-heading > .muted { margin-top: 12px; }
.count-badge { padding: 6px 11px; background: #fbeaea; color: #801823; border-radius: 99px; font-size: .8rem; font-weight: 800; white-space: nowrap; }
.heading-line { display: flex; gap: 15px; align-items: center; justify-content: space-between; }
.cards { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 19px; }
.serial-card {
  display: block; position: relative; overflow: hidden; width: 100%;
  background: white; border: 1px solid var(--border); border-radius: 16px;
  text-align: left; color: var(--navy); padding: 25px 20px 20px;
  box-shadow: 0 4px 14px #0a192f0d, 0 1px 3px #0a192f08; transition: transform .18s, box-shadow .18s;
}
.serial-card::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 6px; background: var(--stripe); }
.serial-card:hover { transform: translateY(-3px); box-shadow: 0 12px 28px #0a192f17, 0 2px 6px #0a192f0a; }
.card-id { font-size: .75rem; font-weight: 800; color: #64748b; letter-spacing: .08em; }
.serial-card h2 { font-size: 1.4rem; margin: 9px 0 17px; overflow-wrap: anywhere; }
.card-meta { display: grid; gap: 11px; font-size: .85rem; }
.card-meta > div { display: grid; gap: 3px; }
.meta-label { font-size: .72rem; color: #64748b; font-weight: 700; }
.card-stage { margin: 16px 0; font-weight: 800; font-size: .82rem; }
.card-progress-text { display: flex; justify-content: space-between; gap: 10px; font-size: .78rem; margin-bottom: 7px; font-weight: 800; }
.mini-track { background: #f1f5f9; height: 8px; border-radius: 99px; overflow: hidden; }
.mini-track > div { height: 100%; border-radius: inherit; background: var(--stripe); }
.session-note { margin-top: 23px; font-size: .8rem; color: #64748b; line-height: 1.6; }
.surface { background: white; border: 1px solid var(--border); border-radius: 18px; padding: 25px; box-shadow: 0 4px 14px #0a192f0d; }
.back-link { display: inline-block; border: 0; background: none; padding: 0; color: #801823; font-weight: 800; margin-bottom: 19px; }
.section-heading { display: flex; align-items: center; justify-content: space-between; gap: 16px; margin-bottom: 23px; }
.record-heading { min-width: 0; }
.record-heading h1 { font-size: clamp(1.6rem, 3vw, 2.2rem); overflow-wrap: anywhere; }
.record-id { font-size: .8rem; color: #64748b; margin-top: 8px; }
.button {
  border: 1.5px solid transparent; border-radius: 10px;
  padding: 11px 17px; font-size: .88rem; font-weight: 800;
  flex-shrink: 0;
}
.primary { background: var(--pink); color: white; }
.primary:hover { background: #69121b; }
.secondary { background: #fff5f5; color: #801823; border-color: #e8b4b8; }
.secondary:hover { background: #fbeaea; }
.neutral { background: white; color: #475569; border-color: var(--border); }
.small-button { padding: 8px 12px; font-size: .76rem; }
.form-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 22px 18px; }
.field { min-width: 0; }
.field-label { display: block; margin-bottom: 8px; font-size: .82rem; font-weight: 800; }
.required { color: #801823; }
.read-value { min-height: 47px; padding: 12px; background: #f8fafc; border: 1px solid var(--border); border-radius: 10px; font-size: .9rem; overflow-wrap: anywhere; }
.read-value.empty { color: #94a3b8; font-style: italic; }
.input-error { border-color: #801823; background: #fff5f5; }
.inline-error { color: #801823; font-size: .8rem; margin-top: 7px; }
.form-actions { display: flex; gap: 12px; margin-top: 26px; border-top: 1px solid #edf2f7; padding-top: 22px; }
.status-pill { display: inline-flex; align-items: center; white-space: nowrap; border-radius: 99px; padding: 5px 9px; font-size: .68rem; font-weight: 800; border: 1px solid; line-height: 1.2; }
.completed { color: #15803d; background: #dcfce7; border-color: #86d6a1; }
.in-progress { color: #b45309; background: #fef3c7; border-color: #f4b471; }
.not-started { color: #475569; background: #f1f5f9; border-color: #e2e8f0; }
.stage-panel { margin-top: 23px; border-top: 5px solid var(--stage-color); }
.stage-panel .section-heading { margin-bottom: 18px; }
.stage-panel-content { display: grid; grid-template-columns: minmax(0, 1fr) 240px; gap: 24px; align-items: start; }
.status-options { display: flex; flex-wrap: wrap; gap: 9px; }
.status-choice { border: 1.5px solid #bac3cf; border-radius: 10px; padding: 10px 13px; font-size: .8rem; font-weight: 800; background: white; color: #334155; }
.status-choice.active { box-shadow: 0 0 0 2px #0a192f; }
.status-choice.completed { background: #dcfce7; color: #15803d; border-color: #86d6a1; }
.status-choice.in-progress { background: #fef3c7; color: #b45309; border-color: #f4b471; }
.status-choice.not-started { background: #f1f5f9; }
.stage-note { margin-top: 16px; }
.progress-section { margin-top: 23px; }
.progress-layout { display: grid; grid-template-columns: minmax(190px, .7fr) minmax(0, 1.3fr); gap: 27px; }
.pie-column { align-self: start; text-align: center; padding-top: 14px; }
.pie-chart { width: 100%; max-width: 295px; height: auto; display: block; margin: 0 auto; }
.pie-note { display: flex; justify-content: center; align-items: center; gap: 8px; font-size: .75rem; margin: 14px 0 8px; }
.sample-solid, .sample-faded { width: 12px; height: 12px; background: #801823; border-radius: 3px; display: inline-block; }
.sample-faded { background: #e8b4b8; margin-left: 8px; }
.overall-summary { display: flex; align-items: center; gap: 16px; margin-bottom: 19px; }
.overall-percent { font-size: 2.8rem; font-weight: 800; color: #801823; letter-spacing: -.05em; }
.overall-summary p { color: #64748b; font-size: .86rem; margin-top: 5px; }
.department-key { display: grid; gap: 12px; }
.department-row { background: #f8fafc; border: 1px solid var(--border); border-radius: 11px; padding: 12px; }
.department-top { display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 9px; }
.department-name { display: flex; align-items: center; gap: 8px; font-size: .83rem; font-weight: 800; }
.color-dot { width: 10px; height: 10px; border-radius: 50%; flex-shrink: 0; }
.department-count { font-size: .78rem; font-weight: 800; margin: 7px 0; color: #475569; }
.missing-tags { display: flex; flex-wrap: wrap; gap: 5px; }
.missing-tag { font-size: .65rem; color: #801823; background: #fff5f5; border: 1px solid #e8b4b8; padding: 3px 7px; border-radius: 6px; }
.all-done { color: #15803d; font-size: .72rem; font-weight: 700; }
.bar-section { margin-top: 30px; padding-top: 23px; border-top: 1px solid #edf2f7; }
.bar-section h3 { margin-bottom: 18px; }
.bar-axis { display: flex; justify-content: space-between; margin: 0 50px 10px 190px; color: #64748b; font-size: .7rem; }
.bar-row { display: grid; grid-template-columns: 180px minmax(0, 1fr) 40px; align-items: center; gap: 10px; margin-bottom: 14px; }
.bar-label { font-size: .77rem; font-weight: 800; }
.bar-value { text-align: right; font-size: .77rem; font-weight: 800; }
.bar-track { height: 18px; border-radius: 5px; overflow: hidden; background: repeating-linear-gradient(to right, #f1f5f9 0%, #f1f5f9 calc(25% - 1px), #e2e8f0 calc(25% - 1px), #e2e8f0 25%); }
.bar-track > div { height: 100%; transition: width .3s; }
.ads-rail { display: grid; gap: 20px; position: sticky; top: 20px; }
.ads-label { font-size: .65rem; text-transform: uppercase; letter-spacing: .18em; font-weight: 800; color: #64748b; text-align: center; margin-bottom: 9px; }
.ad-space {
  min-height: 340px; padding: 20px 16px; border: 2px dashed #e8b4b8;
  border-radius: 16px; display: flex; flex-direction: column;
  align-items: center; justify-content: center; text-align: center;
  background: #fff5f5; color: #64748b; gap: 11px;
}
.ad-space.small-ad { min-height: 250px; }
.ad-icon { font-size: 1.8rem; color: #801823; }
.ad-space h3 { font-size: 1.15rem; }
.ad-space p { font-size: .76rem; line-height: 1.65; }
.ad-image {
  width: 100%; max-height: 250px; object-fit: contain;
  border-radius: 10px; background: white; border: 1px solid var(--border);
}
.ad-file-name {
  max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  font-size: .68rem; font-weight: 700; color: #64748b;
}
.ad-actions { display: flex; gap: 7px; flex-wrap: wrap; justify-content: center; }
.chat-launcher {
  position: fixed; right: clamp(16px, 3vw, 42px); bottom: 24px;
  z-index: 40;
}
.chat-toggle {
  width: 58px; height: 58px; border: 1px solid #801823;
  border-radius: 50%; background: var(--pink); color: white;
  display: grid; place-items: center; font-size: 24px;
  box-shadow: 0 10px 30px #80182340;
}
.chat-toggle:hover { background: #69121b; }
.chatbox {
  position: fixed; right: clamp(16px, 3vw, 42px); bottom: 24px;
  width: min(340px, calc(100vw - 32px));
  z-index: 50; background: white; border: 1px solid var(--border);
  border-radius: 16px; overflow: hidden;
  box-shadow: 0 20px 35px #0a192f1f;
  display: flex; flex-direction: column;
}
.chat-header {
  display: flex; align-items: center; justify-content: space-between; gap: 10px;
  padding: 14px 15px; background: #0a192f; color: white;
}
.chat-header h2 { font-size: 1.05rem; }
.chat-header p { color: #94a3b8; font-size: .64rem; margin-top: 4px; line-height: 1.45; }
.chat-close {
  border: 1px solid #ffffff70; background: transparent; color: white;
  border-radius: 7px; padding: 2px 8px; font-size: 17px; flex-shrink: 0;
}
.chat-close:hover { background: #ffffff20; }
.chat-log {
  padding: 14px; height: 285px; overflow-y: auto;
  display: flex; flex-direction: column; gap: 10px; background: #f8fafc;
}
.chat-message {
  max-width: 92%; border-radius: 12px; padding: 9px 11px;
  font-size: .78rem; line-height: 1.6; overflow-wrap: anywhere;
  white-space: pre-wrap; flex-shrink: 0;
}
.chat-message.assistant { align-self: flex-start; background: #fff5f5; border: 1px solid #e8b4b8; }
.chat-message.user { align-self: flex-end; background: #0a192f; color: white; }
.chat-author { display: block; font-size: .58rem; font-weight: 800; letter-spacing: .06em; margin-bottom: 3px; }
.chat-form { padding: 12px; display: flex; gap: 8px; border-top: 1px solid #edf2f7; }
.chat-form input { padding: 10px 11px; font-size: .8rem; }
.chat-form .button { padding: 10px 12px; font-size: .78rem; }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0,0,0,0); white-space: nowrap; border: 0; }
.toast {
  position: fixed; bottom: 95px; left: 50%; transform: translateX(-50%);
  z-index: 100; max-width: calc(100vw - 32px); width: max-content;
  padding: 14px 18px; background: var(--pink); color: white;
  border: 1px solid #69121b; border-radius: 12px; font-weight: 800;
  font-size: .87rem; box-shadow: 0 10px 35px #80182345;
  display: flex; align-items: center; gap: 15px;
}
.toast-dismiss { color: white; background: transparent; border: 1px solid #ffffff90; border-radius: 5px; padding: 2px 7px; font-size: 18px; }
@media (max-width: 1250px) {
  .workspace { grid-template-columns: minmax(0, 1fr) 225px; gap: 20px; }
  :root { --rail-width: 225px; }
  .cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .surface { padding: 21px; }
  .progress-layout { grid-template-columns: minmax(160px, .65fr) minmax(0, 1.35fr); gap: 18px; }
}
@media (max-width: 1000px) {
  .workspace { grid-template-columns: minmax(0, 1fr); }
  .ads-rail { position: static; grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .ad-space, .ad-space.small-ad { min-height: 215px; }
  .cards { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 780px) {
  .cards { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .form-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .progress-layout { grid-template-columns: 1fr; }
  .pie-chart { max-width: 250px; }
  .stage-panel-content { grid-template-columns: 1fr; }
  .stage-panel-content > div:last-child { max-width: 320px; }
  .bar-row { grid-template-columns: 145px minmax(0, 1fr) 40px; }
  .bar-axis { margin-left: 155px; }
  .navbar { gap: 9px; }
  .brand { font-size: 1.65rem; }
  .brand-logo { height: 36px; }
  .brand-domain { font-size: 1rem; }
  .nav-button { padding: 10px 12px; font-size: .84rem; }
  .kebab { font-size: 24px; }
  .serial-dropdown { position: fixed; top: 82px; left: 16px; right: 16px; width: auto; }
}
@media (max-width: 520px) {
  .navbar { flex-wrap: wrap; padding: 13px 16px; min-height: 114px; }
  .brand { flex-basis: calc(100% - 65px); }
  .brand-logo { height: 34px; }
  .kebab-container { position: absolute; right: 16px; top: 13px; }
  .serial-dropdown { top: 118px; }
  .stage-dropdown { top: 48px; }
  .workspace { padding-top: 22px; }
  .cards, .form-grid, .ads-rail { grid-template-columns: 1fr; }
  .section-heading { align-items: flex-start; flex-wrap: wrap; }
  .surface { padding: 18px; }
  .heading-line { align-items: flex-start; }
  .bar-row { grid-template-columns: minmax(0, 1fr) 42px; gap: 7px; margin-bottom: 18px; }
  .bar-label { grid-column: 1 / -1; }
  .bar-axis { margin-left: 0; margin-right: 49px; }
  .chat-toggle, .chatbox { right: 16px; }
  .chat-toggle { bottom: 16px; }
  .chatbox { bottom: 16px; }
  .chat-log { height: min(65vh, 350px); }
  .toast { bottom: 90px; font-size: .8rem; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; animation: none !important; }
}

/* About section (landing page, below the navbar) */
.about {
  display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); gap: 28px;
  position: relative; overflow: hidden; color: #0a192f;
  padding: clamp(24px, 4vw, 44px); border-radius: 22px;
  background: #fff;
  border: 1px solid var(--border);
  box-shadow: 0 4px 14px #0a192f0d, 0 1px 3px #0a192f08;
}
.about::after {
  content: ''; position: absolute; right: -80px; top: -100px; width: 300px; height: 300px;
  border-radius: 50%; background: radial-gradient(circle, #80182322, transparent 70%); pointer-events: none;
}
.about > * { position: relative; z-index: 1; min-width: 0; }
.about .eyebrow { color: #801823; }
.about h1 { font-size: clamp(2.3rem, 5vw, 3.7rem); color: #0a192f; letter-spacing: -.02em; }
.about-tagline { font-family: 'Fraunces', Georgia, serif; font-size: clamp(1.1rem, 2vw, 1.4rem); color: #801823; margin: 10px 0 14px; }
.about-body { line-height: 1.75; color: #475569; font-size: .95rem; max-width: 60ch; }
.about-actions { display: flex; gap: 12px; flex-wrap: wrap; align-items: center; margin-top: 22px; }
.about-link { border: 1px solid #e8b4b8; background: transparent; color: #801823; border-radius: 10px; padding: 11px 17px; font-weight: 800; font-size: .88rem; }
.about-link:hover { background: #fff5f5; }
.about-stats { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; margin: 0 0 18px; }
.about-stats div { background: #f8fafc; border: 1px solid var(--border); border-radius: 14px; padding: 14px 10px; text-align: center; }
.about-stats dt { font-size: .68rem; font-weight: 700; color: #64748b; }
.about-stats dd { margin: 6px 0 0; font-family: 'Fraunces', Georgia, serif; font-size: 2rem; font-weight: 700; line-height: 1; color: #0a192f; }
.about-points { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }
.about-points li { display: grid; gap: 3px; padding: 12px 14px; border-left: 4px solid #801823; background: #fff5f5; border-radius: 0 12px 12px 0; }
.about-points strong { font-size: .88rem; color: #0a192f; }
.about-points span { font-size: .78rem; color: #475569; line-height: 1.55; }
@media (max-width: 1000px) { .about { grid-template-columns: minmax(0, 1fr); } }
@media (max-width: 520px) { .about-stats { gap: 7px; } .about-stats dd { font-size: 1.6rem; } }
`;
